```bash
cd /home/vscode/nullness-benchmarks/libgdx && sed -i '89,92c\  public SelectBox(SelectBoxStyle style) {
    if (style == null) throw new IllegalArgumentException("style cannot be null.");
    this.style = style;
    setSize(getPrefWidth(), getPrefHeight());

    selection.setActor(this);
    selection.setRequired(true);

    scrollPane = newScrollPane();' gdx/src/com/badlogic/gdx/scenes/scene2d/ui/SelectBox.java
